import{_ as c}from"./breadcrumb-Bouxb_Ji-1788838101366.js";import{_ as d,c as e,e as o,n,o as s}from"./index-f8g0bVp--1788838101366.js";const i={},v={class:"main-container"};function _(r,a){const t=c;return s(),e("div",v,[o(t,{title:"案例选登正文"}),a[0]||(a[0]=n('<div class="content-container" data-v-c5040d4b><div class="content-box" data-v-c5040d4b><div class="title" data-v-c5040d4b>案例选登详情</div><div class="case-info__title" data-v-c5040d4b><h2 data-v-c5040d4b>农村网络信号差通信不便问题</h2></div><div class="case-info__content" data-v-c5040d4b><p data-v-c5040d4b> 2024-08-16 网民反映： 会泽县迤车镇小河村袁家沟小组，网络信号极差，打电话都是无法接通的，虽然部分是有宽带，但是有部分没有拉宽带。希望政府部门领导帮我们解决移动网络问题，通话信号问题。 </p></div><div class="case-info__footer" data-v-c5040d4b><h3 data-v-c5040d4b>2024-08-20 会泽县迤车镇回复：</h3><p data-v-c5040d4b> 经调查核实，您所在地属迤车镇小河村委会袁家沟小组坪子上（苏家坪），居住位置位于山沟间，总计10余户人居住，由于移动、电信、联通公司信号基站位于该地后山背上，受地形地势影响，导致手机信号受阻，存在信号不稳定、有时无网络信号的情况。经迤车电信所工作人员实地勘察，已获会泽电信公司批复在该地安装小型信号基站，但由于受地理条件限制，选址安装等存在困难，受雨季天气影响，对施工进度造成影响。目前，覆盖该地区的小型信号基站正在建设中。 下一步，迤车镇将持续跟进信号基站安装进度，确保尽快完成建设，实现该地信号全覆盖。 感谢您对我们工作的支持和关心，祝您身体健康，生活愉快！ </p></div></div></div>',1))])}const p=d(i,[["render",_],["__scopeId","data-v-c5040d4b"]]);export{p as default};
